/bin/bash -lc "python3 - <<'PY'
import pathlib
import subprocess
import tempfile

with tempfile.TemporaryDirectory(prefix='cpp-trim-check-', dir='/tmp') as directory:
    check = str(pathlib.Path(directory) / 'check')
    subprocess.run(['c++', '-std=c++17', '-Wall', '-Wextra', '-o', check, 'check.cpp'], check=True)
    subprocess.run([check], check=True)
    print('Existing check passed.')
    edge_check = str(pathlib.Path(directory) / 'edge-check')
    source = r'''
#include <cassert>
#include \"service.hpp\"
int main() {
    assert(trim(\"\").empty());
    assert(trim(\" \\t\\r\\n\\n\\r\\t \").empty());
    assert(trim(\"\\t\\r\\n value \\n\\r\\t\") == \"value\");
    assert(trim(\" \\ta\\t b\\r\\nc\\n \") == \"a\\t b\\r\\nc\");
    assert(trim(\" \\v\\f \") == \"\\v\\f\");
    assert(trim(std::string(\" \\t\\0x\\0\\r\\n\", 7)) == std::string(\"\\0x\\0\", 3));
}
'''
    subprocess.run(['c++', '-std=c++17', '-Wall', '-Wextra', '-I', '.', '-x', 'c++', '-o', edge_check, '-'], input=source, text=True, check=True)
    subprocess.run([edge_check], check=True)
    print('Whitespace and interior-byte edge checks passed.')
PY
cat service.hpp
git status --short"

